import {seed,status,transact,createDemo,validateLaunch,DEMO_USER} from './demo.js';
import {Chain,validAddress} from './chain.js';
import defaults from './config.js';
import {introLanding, introHeader} from './landing.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:d}),short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'Not connected';
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let demo=read('tl-demo-v1',seed());if(demo.version!==1||!Array.isArray(demo.sales))demo=seed();
let config={...defaults,...read('tl-config',{})},chain=new Chain(config),mode=read('tl-mode','demo'),sales=[],loading=false,loadError='',busy=false,filter='All',query='',lastHash='';
if(!['demo','live'].includes(mode))mode='demo';
const user=()=>mode==='demo'?DEMO_USER:chain.account;
const now=()=>mode==='demo'?demo.clock:chain.time||Math.floor(Date.now()/1000);
const all=()=>mode==='demo'?demo.sales:sales;
const current=()=>location.hash.slice(1)||'/';
const money=()=>mode==='demo'?'USDC':chain.paymentSymbol||'USDC';
function persist(){localStorage.setItem('tl-demo-v1',JSON.stringify(demo));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
function progress(s){return Math.max(0,Math.min(100,s.raised/s.hardCap*100));}
function badge(s){const st=status(s,now());return `<span class="badge ${st==='Live'?'green':st==='Failed'?'red':st==='Successful'?'green':'neutral'}">${st==='Live'?'<i></i>':''}${esc(st)}</span>`;}
function icon(name){const paths={arrow:'M7 17 17 7M7 7h10v10',plus:'M12 5v14M5 12h14',wallet:'M20 8V5H4v14h16V8H4m16 4h-5v4h5',check:'m5 12 4 4 10-10',back:'m12 5-7 7 7 7M5 12h14',search:'m20 20-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',copy:'M9 9h11v11H9zM4 15H3V3h12v1',close:'m6 6 12 12M6 18 18 6',chevron:'m8 4 8 8-8 8'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.arrow).split('|').map(p=>`<path d="${p}"/>`).join('')}</svg>`;}
function header(){const p=current();if(p==='/')return introHeader(icon);return `<header><a class="brand" href="#/" aria-label="TokenLaunchpad home"><b class="mark">T<span>↗</span></b><span>TokenLaunchpad<span class="brand-dot">.</span></span></a><nav aria-label="Main navigation"><a class="${p==='/explore'?'active':''}" href="#/explore">Explore</a><a class="${p==='/create'?'active':''}" href="#/create">Create launch</a><a class="${p==='/dashboard'?'active':''}" href="#/dashboard">Dashboard</a><a class="${p==='/guide'?'active':''}" href="#/guide">How it works</a></nav><div class="header-actions"><div class="mode" aria-label="Operating mode"><button data-mode="demo" class="${mode==='demo'?'selected':''}">Demo</button><button data-mode="live" class="${mode==='live'?'selected':''}">On-chain</button></div><button class="button wallet small" data-action="connect">${icon('wallet')}<span>${mode==='demo'?'Demo wallet':chain.account?short(chain.account):'Connect wallet'}</span></button></div></header>`;}
function footer(){return `<footer><a class="brand" href="#/"><b class="mark small-mark">T</b>TokenLaunchpad.</a><span>Built on contracts. Not promises.</span><div><a href="#/guide">Documentation</a><a href="#/setup">Network setup</a><span class="muted">Testnet portfolio project · Unaudited</span></div></footer>`;}
function modeBar(){return `<div class="context-bar"><span>${mode==='demo'?'<b>DEMO SANDBOX</b> Simulated funds · saved only in this browser':`<b>ON-CHAIN</b> ${esc(config.chainName)} · ${esc(money())} payments`}</span><a href="#/setup">${mode==='demo'?'Ready for a testnet?':'Network settings'} ${icon('arrow')}</a></div>`;}
function tokenMark(s,large=false){return `<span class="token-mark ${large?'large':''} color-${['NOVA','ORB','LUM','ECHO'].indexOf(s.symbol)+1}">${esc(s.symbol.slice(0,1))}<small>↗</small></span>`;}
function card(s){return `<a class="launch-card" href="#/launch/${encodeURIComponent(s.id)}"><div class="card-head">${tokenMark(s)}${badge(s)}</div><div class="card-title"><h3>${esc(s.name)}</h3><span>$${esc(s.symbol)}</span></div><p class="card-description">${esc(s.description||'A fixed-price token presale, settled directly on-chain.')}</p><div class="card-tags"><span>${esc(s.tag||'Community')}</span><span>Fixed price</span></div><div class="raised-label"><span>${fmt(s.raised)} <small>${esc(money())} raised</small></span><b>${fmt(progress(s),1)}%</b></div><div class="progress" role="progressbar" aria-label="Funding progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress(s)}"><i style="width:${progress(s)}%"></i></div><div class="card-bottom"><span>1 ${esc(money())} = ${fmt(s.rate,4)} ${esc(s.symbol)}</span><b>${icon('arrow')}</b></div></a>`;}
function landing(){return introLanding(icon);}
function pageHead(kicker,title,desc,action=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function empty(title,desc,link='#/create',label='Create a launch'){return `<div class="empty">${icon('grid')}<h3>${title}</h3><p>${desc}</p><a class="button secondary" href="${link}">${label} ${icon('arrow')}</a></div>`;}
function chainNotice(){if(loading)return `<div class="empty"><div class="spinner"></div><h3>Reading the blockchain</h3><p>Fetching launch terms and account balances directly from the RPC.</p></div>`;if(loadError)return `<div class="callout danger"><h3>Could not load on-chain launches</h3><p>${esc(loadError)}</p><a class="button secondary" href="#/setup">Open setup</a><button class="button secondary" data-action="refresh">Retry</button></div>`;return '';}
function explore(){const list=all().filter(s=>(filter==='All'||status(s,now())===filter)&&(`${s.name} ${s.symbol}`.toLowerCase().includes(query.toLowerCase())));const live=all().filter(s=>status(s,now())==='Live').length;return `<main class="workspace">${pageHead('DISCOVER WHAT’S NEXT','Early ideas. <em>Real potential.</em>',mode==='demo'?'Explore sample launches. Every action here uses simulated funds.':'Explore fixed-price presales directly from the deployed factory.',`<a class="button primary" href="#/create">Create launch ${icon('plus')}</a>`)}<div class="stats-strip"><div><small>${mode==='demo'?'SIMULATED VOLUME':'TOTAL CONTRIBUTIONS'}</small><strong>${fmt(all().reduce((a,s)=>a+s.raised,0))}<span> ${esc(money())}</span></strong></div><div><small>OPEN PRESALES</small><strong>${live.toString().padStart(2,'0')}</strong></div><div><small>PLATFORM FEE</small><strong>2<span>% · successful sales only</span></strong></div><div><small>SETTLEMENT</small><strong class="text-stat">On-chain<span>Claims & refunds</span></strong></div></div><div class="list-controls"><div class="filters" role="group" aria-label="Filter launches">${['All','Live','Upcoming','Successful','Failed'].map(f=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${f}</button>`).join('')}</div><label class="search">${icon('search')}<input id="search" placeholder="Search name or symbol" value="${esc(query)}" aria-label="Search launches"></label></div>${chainNotice()||`<div class="cards">${list.map(card).join('')}</div>${!list.length?empty('No launches found',query?'Try another name or remove a filter.':mode==='live'?'Deploy your first launch or check your network configuration.':'Create a launch to get started.'):''}`}<p class="risk-note">${icon('shield')} Listing is not endorsement. Contracts are unaudited. Use test funds only.</p></main>`;}
function detail(id){const s=all().find(x=>x.id===id);if(!s)return `<main class="workspace">${chainNotice()||empty('Launch not found','Check your mode and network, or return to Explore.','#/explore','Explore launches')}</main>`;const st=status(s,now()),u=user(),owned=u&&s.creator.toLowerCase()===u.toLowerCase(),allocation=s.allocations[u]||0,contribution=s.contributions[u]||0;const tokensLeft=Math.max(0,s.hardCap-s.raised);return `<main class="workspace"><a class="back-link" href="#/explore">${icon('back')} All launches</a><div class="detail-header">${tokenMark(s,true)}<div><span class="eyebrow">${esc(s.tag)} / FIXED-PRICE PRESALE</span><h1>${esc(s.name)} <small>$${esc(s.symbol)}</small></h1></div>${badge(s)}</div><div class="detail-grid"><div><section class="surface funding"><div class="section-label">FUNDING OVERVIEW <span>${fmt(progress(s),1)}% of hard cap</span></div><h2>${fmt(s.raised,2)} <small>/ ${fmt(s.hardCap)} ${esc(money())}</small></h2><div class="progress large-progress"><i style="width:${progress(s)}%"></i></div><div class="funding-grid"><div><small>Soft cap</small><b>${fmt(s.softCap)} ${esc(money())}</b></div><div><small>Presale allocation</small><b>${fmt(s.hardCap*s.rate)} ${esc(s.symbol)}</b></div><div><small>Start time</small><b>${esc(new Date(s.start*1000).toLocaleString())}</b></div><div><small>End time</small><b>${esc(new Date(s.end*1000).toLocaleString())}</b></div></div></section><section class="surface"><h3>About this launch</h3><p>${esc(s.description)}</p><div class="tokenomics"><span>Total supply <b>${fmt(s.supply)} ${esc(s.symbol)}</b></span><span>Price <b>1 ${esc(money())} = ${fmt(s.rate,6)} ${esc(s.symbol)}</b></span><span>Per-wallet limit <b>${fmt(s.minBuy)} – ${fmt(s.maxBuy)} ${esc(money())}</b></span><span>Creator <b>${short(s.creator)} <button class="icon-button" aria-label="Copy creator address" data-copy="${esc(s.creator)}">${icon('copy')}</button></b></span>${s.token?`<span>Token contract <a target="_blank" rel="noopener" href="${esc(config.explorer)}/address/${s.token}">${short(s.token)} ↗</a></span><span>Sale contract <a target="_blank" rel="noopener" href="${esc(config.explorer)}/address/${s.id}">${short(s.id)} ↗</a></span>`:''}</div></section><section class="surface compact"><h3>${icon('shield')} Clear rules. Locked terms.</h3><p>Tokens are reserved in the sale contract before purchases open. If the soft cap is missed, each contributor can claim a full refund after finalization. This does not guarantee token value or project quality.</p></section>${mode==='demo'?`<section class="surface demo-controls"><div><span class="eyebrow">SANDBOX CONTROLS</span><h3>Try the entire lifecycle.</h3><p>Advance the simulated clock for all demo sales. No blockchain transaction.</p></div><div class="button-row"><button class="button secondary small" data-action="advance-start" data-id="${s.id}">Jump to start</button><button class="button secondary small" data-action="advance-end" data-id="${s.id}">Jump past deadline</button></div></section>`:''}</div><aside><section class="surface purchase"><div class="section-label">YOUR ALLOCATION ${icon('wallet')}</div><h2>${fmt(allocation,4)} <small>${esc(s.symbol)}</small></h2><p>Contributed: ${fmt(contribution,2)} ${esc(money())}</p>${st==='Live'?`<form id="buy-form" data-id="${s.id}"><label for="amount">You pay <span>Balance: ${fmt(mode==='demo'?demo.balance:chain.balance,2)}</span></label><div class="amount-input"><input id="amount" name="amount" type="number" min="${s.minBuy}" max="${Math.min(tokensLeft,s.maxBuy-contribution)}" step="0.000001" placeholder="0.00" required><span>${esc(money())}</span></div><div class="quote"><span>You receive</span><b id="quote-amount">0 ${esc(s.symbol)}</b></div><button class="button primary wide" ${busy?'disabled':''}>${mode==='demo'?'Buy with demo USDC':u?'Approve & buy tokens':'Connect wallet & buy'} ${icon('arrow')}</button><small class="help">${mode==='demo'?'Simulation only. No wallet signature or real funds.':'Approval and purchase may require two wallet confirmations.'}</small></form>`:`<div class="sale-status">${st==='Needs funding'?'Creator must deposit sale tokens before the start time.':st==='Upcoming'?'Purchases open at the scheduled start time.':st==='Awaiting finalization'?'The sale is closed. Anyone can finalize the outcome.':s.successful?'Sale successful. Reserved tokens are ready to claim.':'Soft cap missed. Contributors can claim their payment back.'}</div>`}<div class="settle-actions">${st==='Awaiting finalization'?`<button class="button primary wide" data-tx="finalize" data-id="${s.id}">Finalize sale ${icon('check')}</button>`:''}${s.finalized&&s.successful&&allocation>0?`<button class="button primary wide" data-tx="claim" data-id="${s.id}" ${s.claimed[u]?'disabled':''}>${s.claimed[u]?'Tokens claimed ✓':'Claim '+fmt(allocation)+' '+esc(s.symbol)}</button>`:''}${s.finalized&&!s.successful&&contribution>0?`<button class="button primary wide" data-tx="refund" data-id="${s.id}" ${s.refunded[u]?'disabled':''}>${s.refunded[u]?'Refund claimed ✓':'Claim '+fmt(contribution)+' '+esc(money())+' refund'}</button>`:''}${mode==='live'&&!u?'<button class="button secondary wide" data-action="connect">Connect to see your allocation</button>':''}</div></section>${owned?`<section class="surface creator-controls"><span class="eyebrow">CREATOR CONTROLS</span><h3>Your launch, at a glance.</h3>${!s.funded&&!s.finalized&&now()<s.start?`<p>Reserve ${fmt(s.hardCap*s.rate)} ${esc(s.symbol)} to open this presale.</p><button class="button primary wide" data-tx="fund" data-id="${s.id}">Approve & fund sale</button>`:''}${s.finalized&&s.successful?`<p>Net proceeds: ${fmt(s.raised*.98,2)} ${esc(money())}<br>Platform fee: ${fmt(s.raised*.02,2)} ${esc(money())}</p><button class="button secondary wide" data-tx="withdraw" data-id="${s.id}" ${s.withdrawn?'disabled':''}>${s.withdrawn?'Proceeds withdrawn ✓':'Withdraw proceeds'}</button>`:''}${s.finalized&&s.funded?`<button class="button secondary wide" data-tx="recover" data-id="${s.id}" ${s.recovered?'disabled':''}>${s.recovered?'Unsold tokens recovered ✓':'Recover unsold tokens'}</button>`:''}<small class="help">Buyer allocations stay reserved when unsold tokens are recovered.</small></section>`:''}<p class="side-note">${icon('shield')} ${mode==='demo'?'Demo data is stored only on this device.':'Your wallet signs. Smart contracts settle.'}</p></aside></div></main>`;}
const field=(name,label,value,type='number',help='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0.000001" max="1000000000" step="any"':type==='text'?'maxlength="48"':''} required>${help?`<small>${help}</small>`:''}</label>`;
function create(){const date=t=>{const d=new Date(t*1000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};return `<main class="workspace narrow">${pageHead('FROM IDEA TO ON-CHAIN','Make your <em>first move.</em>','Create a fixed-supply token and a presale with immutable terms.')}<form id="create-form"><div class="create-grid"><div><section class="surface"><div class="form-heading"><span>01</span><div><h3>Token identity</h3><p>A name your community can rally behind.</p></div></div><div class="form-grid">${field('name','Token name','', 'text','Example: Spydy Token')}${field('symbol','Token symbol','','text','1–10 uppercase letters or numbers')}${field('supply','Total supply','1000000','number','18-decimal fixed supply. No additional minting.')}${field('rate',`Tokens per 1 ${esc(money())}`,'10','number','Fixed for the entire sale.')}</div></section><section class="surface"><div class="form-heading"><span>02</span><div><h3>Presale terms</h3><p>Clear limits, defined before the first contribution.</p></div></div><div class="form-grid">${field('softCap',`Soft cap (${esc(money())})`,'10000','number','Below this target, contributors get refunds.')}${field('hardCap',`Hard cap (${esc(money())})`,'40000','number','Maximum total contributions.')}${field('minBuy',`Minimum purchase (${esc(money())})`,'10')}${field('maxBuy',`Maximum per wallet (${esc(money())})`,'5000')}${field('start','Starts at',date(now()+3600),'datetime-local','Your local timezone. Allow time to deposit tokens.')}${field('end','Ends at',date(now()+7*86400),'datetime-local')}</div></section></div><aside><section class="surface sticky"><span class="eyebrow">LAUNCH SUMMARY</span><h3 id="preview-name">Your next chapter.</h3><div class="tokenomics"><span>Required sale tokens<b id="required-tokens">400,000</b></span><span>Payment token<b>${esc(money())}</b></span><span>Platform fee<b>2% on success</b></span><span>Mint authority<b>None</b></span><span>Mode<b>${mode==='demo'?'Local simulation':esc(config.chainName)}</b></span></div><div class="callout"><p>After deployment, approve and deposit the required sale tokens <b>before the start time</b>. Sale terms cannot be edited.</p></div><label class="checkbox"><input name="terms" type="checkbox" required><span>I understand the terms are immutable and these contracts are unaudited.</span></label><button class="button primary wide" ${busy?'disabled':''}>${mode==='demo'?'Create demo launch':'Deploy token & sale'} ${icon('arrow')}</button><small class="help">${mode==='demo'?'No wallet needed. Nothing is sent to a blockchain.':'A wallet signature and testnet ETH for gas are required.'}</small></section></aside></div></form></main>`;}
function dashboard(){const u=user(),positions=all().filter(s=>(s.contributions[u]||0)>0),owned=all().filter(s=>u&&s.creator.toLowerCase()===u.toLowerCase());return `<main class="workspace">${pageHead('YOUR LAUNCH CONTROL','Everything, <em>in one place.</em>',mode==='demo'?'Your simulated portfolio and creator launches.':u?`Connected account: ${short(u)}`:'Connect your wallet to load your contributions and launches.',`<a class="button primary" href="#/create">New launch ${icon('plus')}</a>`)}<div class="stats-strip"><div><small>${mode==='demo'?'DEMO BALANCE':'WALLET BALANCE'}</small><strong>${fmt(mode==='demo'?demo.balance:chain.balance,2)}<span> ${esc(money())}</span></strong></div><div><small>YOUR CONTRIBUTIONS</small><strong>${fmt(positions.reduce((a,s)=>a+(s.contributions[u]||0),0))}<span> ${esc(money())}</span></strong></div><div><small>POSITIONS</small><strong>${positions.length.toString().padStart(2,'0')}</strong></div><div><small>YOUR LAUNCHES</small><strong>${owned.length.toString().padStart(2,'0')}</strong></div></div>${chainNotice()}${mode==='live'&&!u?`<div class="empty">${icon('wallet')}<h3>Your portfolio is wallet-connected.</h3><p>Connect to see allocations and creator controls.</p><button class="button primary" data-action="connect">Connect wallet</button></div>`:`<div class="section-heading"><h2>Your allocations</h2><span>${positions.length} positions</span></div><div class="positions">${positions.map(s=>`<a href="#/launch/${s.id}" class="position-row"><div class="position-identity">${tokenMark(s)}<div><b>${esc(s.name)}</b><span>${fmt(s.contributions[u],2)} ${esc(money())} contributed</span></div></div><div><b>${fmt(s.allocations[u],4)} ${esc(s.symbol)}</b><span>${s.claimed[u]?'Claimed':s.refunded[u]?'Refunded':'Allocated'}</span></div>${badge(s)}${icon('chevron')}</a>`).join('')||empty('No allocations yet','Explore a launch to make your first contribution.','#/explore','Explore launches')}</div><div class="section-heading"><h2>Your launches</h2><span>${owned.length} created</span></div><div class="cards">${owned.map(card).join('')}</div>${!owned.length?empty('Ready for your first launch?','Create your token and define its presale terms.'):''}`}${mode==='demo'?`<section class="surface demo-wallet"><div><h3>Your demo token balances</h3><p>${Object.entries(demo.tokens).length?Object.entries(demo.tokens).map(([s,n])=>`${fmt(n,4)} ${esc(s)}`).join(' · '):'Claim a successful sale to receive simulated tokens.'}</p></div><button class="button secondary small" data-action="reset">Reset sandbox</button></section>`:''}</main>`;}
function guide(){return `<main class="workspace narrow">${pageHead('THE FIELD GUIDE','A launch, <em>without the guesswork.</em>','One fixed-supply token. One presale contract. A transparent outcome.')}<div class="guide-steps">${[
 ['Create your launch','Set the token name, supply, sale price, caps, wallet limits and dates. The factory deploys a new ERC20 and a separate sale contract. All terms are immutable.'],
 ['Reserve the sale tokens','As creator, approve the sale contract and deposit hard cap × token rate. Do this before the start time. A sale without inventory cannot accept contributions.'],
 ['Let the community contribute','Buyers approve the exact payment amount, then buy tokens during the sale window. Payments stay in the sale contract. Allocations are recorded; tokens are not delivered yet.'],
 ['Finalize the outcome','After the deadline—or as soon as the hard cap is reached—anyone can finalize. Contracts do not execute themselves: someone must send this transaction.'],
 ['Claim tokens or refunds','If the soft cap is reached, contributors claim tokens and the creator withdraws 98% of raised funds. The fixed 2% fee goes to the deployment treasury. If the sale fails, each contributor claims their full contribution back.'],
 ['Recover only unsold tokens','After finalization, the creator can recover unsold inventory. Successful buyers’ unclaimed tokens remain reserved. There is no deadline on buyer claims in this implementation.']
 ].map(([title,body],i)=>`<section class="guide-step"><span>0${i+1}</span><div><h2>${title}</h2><p>${body}</p></div></section>`).join('')}</div><div class="two-col"><section class="surface"><h3>Try a success in demo</h3><p>Open Lumen Finance → Finalize sale → Claim tokens. This demo also makes you the creator, so you can test withdrawing proceeds.</p><a class="text-link" href="#/launch/demo-lumen" data-demo-link>Try successful settlement ${icon('arrow')}</a></section><section class="surface"><h3>Try a failed sale</h3><p>Echo Labs missed its soft cap. Open it and claim the pre-seeded 100 demo USDC refund. No wallet or real payment is involved.</p><a class="text-link" href="#/launch/demo-echo" data-demo-link>Try a refund ${icon('arrow')}</a></section></div><section class="surface"><h3>What this version intentionally does not do</h3><p>No custom backend, user database, Supabase, off-chain custody, automatic DEX listing, vesting, AI agents or return guarantees. The frontend reads contracts over RPC; wallet transactions change on-chain state. Demo data and network preferences are stored only in this browser.</p><p class="warning-text">Portfolio / testnet software. Not audited or ready to hold real money.</p></section></main>`;}
function setup(){return `<main class="workspace narrow">${pageHead('CONNECT YOUR DEPLOYMENT','Your contracts. <em>Your network.</em>','Configure a local Anvil/Ganache chain or a testnet. Never enter a private key here.')}<div class="two-col"><form id="setup-form" class="surface"><h3>Public connection settings</h3>${field('chainName','Network name',config.chainName,'text')}${field('chainId','Chain ID',config.chainId)}${field('rpcUrl','HTTP RPC URL',config.rpcUrl,'url')}${field('factoryAddress','LaunchpadFactory address',config.factoryAddress,'text')}${field('paymentTokenAddress','Payment token address',config.paymentTokenAddress,'text')}${field('explorer','Explorer URL',config.explorer,'url')}<button class="button primary wide">Save & verify connection ${icon('arrow')}</button><small class="help">Saved in this browser only. RPC endpoints must support browser CORS. Local HTTP RPC can be blocked on an HTTPS hosted page; run the frontend locally for local chains.</small></form><div><section class="surface"><span class="eyebrow">START HERE</span><h3>Deploy once. Connect directly.</h3><ol class="instructions"><li>Install the project dependencies.</li><li>Start the local chain with <code>npm run chain</code>.</li><li>Run <code>npm run deploy:local</code> in another terminal.</li><li>Start the UI with <code>npm run dev</code>. Deployment writes local addresses to the config.</li><li>Add the local network to MetaMask: RPC <code>http://127.0.0.1:8545</code>, chain ID <code>31337</code>.</li><li>Import a disposable account shown by the local chain. Never use a funded mainnet wallet for development.</li></ol></section><section class="surface"><h3>Testnet setup</h3><p>Use the included Foundry deployment script with your encrypted wallet keystore. Deploy the payment token and factory, then paste their addresses here. Read the README for exact commands.</p><p>Live mode never silently falls back to simulated data. If a contract cannot be reached, it will show an error.</p></section></div></div></main>`;}
function render(){const path=current();let content=path==='/'?landing():path==='/explore'?explore():path==='/create'?create():path==='/dashboard'?dashboard():path==='/guide'?guide():path==='/setup'?setup():path.startsWith('/launch/')?detail(decodeURIComponent(path.slice(8))):`<main class="workspace">${empty('Page not found','Return to the launch workspace.','#/explore','Explore launches')}</main>`;$('#app').innerHTML=header()+(path!=='/'?modeBar():'')+content+footer();if(busy)document.querySelectorAll('button').forEach(b=>b.disabled=true);}
async function refresh(){if(mode==='demo'){loading=false;loadError='';render();return;}loading=true;loadError='';render();try{sales=await chain.load();}catch(e){sales=[];loadError=e.shortMessage||e.message;}finally{loading=false;render();}}
async function setMode(value){if(busy)return;mode=value;localStorage.setItem('tl-mode',JSON.stringify(mode));loadError='';await refresh();}
async function runTx(id,action,amount){if(busy)return;busy=true;render();try{if(mode==='demo'){demo=transact(demo,id,action,amount);persist();toast('Demo '+({buy:'purchase complete',fund:'inventory deposited',finalize:'sale finalized',claim:'tokens claimed',refund:'refund received',withdraw:'proceeds withdrawn',recover:'unsold tokens recovered'}[action]||'action complete')+'. No real funds moved.');}else{lastHash=await chain.send(id,action,amount,toast);toast('Transaction confirmed: '+short(lastHash));await refresh();}}catch(e){toast(e.shortMessage||e.message);}finally{busy=false;render();}}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
 if(b.dataset.demoLink!==undefined&&mode!=='demo'){await setMode('demo');}
 if(b.dataset.mode){await setMode(b.dataset.mode);return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Address copied.');}catch{toast('Clipboard unavailable. Address: '+b.dataset.copy);}return;}
 if(b.dataset.tx){await runTx(b.dataset.id,b.dataset.tx);return;}
 const a=b.dataset.action;if(!a)return;
 if(a==='connect'){if(mode==='demo'){location.hash='/dashboard';toast('Demo wallet uses simulated funds. Switch to On-chain to connect MetaMask.');return;}try{await chain.connect();await refresh();toast('Wallet connected.');}catch(err){toast(err.shortMessage||err.message);}return;}
 if(a==='refresh'){await refresh();return;}
 if(a==='reset'){if(confirm('Reset all simulated launches, balances and purchases in this browser? Real wallet funds are unaffected.')){demo=seed();persist();render();toast('Sandbox reset.');}return;}
 if(a.startsWith('advance-')){const s=demo.sales.find(x=>x.id===b.dataset.id);demo.clock=Math.max(demo.clock,a==='advance-start'?s.start:s.end+1);persist();render();toast('Demo clock advanced for all sample sales.');}
});
document.addEventListener('input',e=>{
 if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}
 if(e.target.id==='amount'){const s=all().find(s=>s.id===$('#buy-form').dataset.id);$('#quote-amount').textContent=`${fmt(Number(e.target.value||0)*s.rate,6)} ${s.symbol}`;}
 if(e.target.closest('#create-form')){const f=new FormData($('#create-form'));$('#preview-name').textContent=f.get('name')||'Your next chapter.';$('#required-tokens').textContent=fmt(Number(f.get('hardCap'))*Number(f.get('rate')));}
});
document.addEventListener('submit',async e=>{
 e.preventDefault();if(busy)return;const f=e.target,values=Object.fromEntries(new FormData(f));
 if(f.id==='buy-form'){await runTx(f.dataset.id,'buy',values.amount);return;}
 if(f.id==='create-form'){
  try{const input={name:values.name.trim(),symbol:values.symbol.trim().toUpperCase(),supply:Number(values.supply),rate:Number(values.rate),softCap:Number(values.softCap),hardCap:Number(values.hardCap),minBuy:Number(values.minBuy),maxBuy:Number(values.maxBuy),start:Math.floor(new Date(values.start).getTime()/1000),end:Math.floor(new Date(values.end).getTime()/1000)};validateLaunch(input,now());
   busy=true;f.querySelector('button[type="submit"],button').disabled=true;let id;
   if(mode==='demo'){const result=createDemo(demo,input);demo=result.state;id=result.id;persist();}else{const result=await chain.create(input,toast);id=result.id;lastHash=result.hash;await refresh();}
   toast('Launch created. Next: deposit the sale tokens before the start time.');location.hash='/launch/'+id;
  }catch(err){toast(err.shortMessage||err.message);}finally{busy=false;if(current()==='/create'){f.querySelector('button').disabled=false;}else render();}return;
 }
 if(f.id==='setup-form'){
  try{const rpc=new URL(values.rpcUrl),explorer=new URL(values.explorer);if(!['https:','http:'].includes(rpc.protocol)||!['https:','http:'].includes(explorer.protocol))throw Error('Use HTTP or HTTPS URLs.');if(!validAddress(values.factoryAddress)||!validAddress(values.paymentTokenAddress))throw Error('Enter valid nonzero deployed contract addresses.');const id=Number(values.chainId);if(!Number.isSafeInteger(id)||id<=0)throw Error('Invalid chain ID.');
   const next={...values,chainId:id,rpcUrl:rpc.href,explorer:explorer.href.replace(/\/$/,'')};const test=new Chain(next);toast('Checking the network and factory…');await test.verifiedFactory();config=next;chain=test;localStorage.setItem('tl-config',JSON.stringify(config));toast('Connection verified and saved.');await setMode('live');location.hash='/explore';
  }catch(err){toast(err.shortMessage||err.message);}
 }
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.ethereum?.on?.('accountsChanged',()=>{chain.account=null;toast('Wallet account changed. Reconnect to refresh your portfolio.');refresh();});
window.ethereum?.on?.('chainChanged',()=>{chain.account=null;chain.provider=null;toast('Wallet network changed. Reconnect before transacting.');refresh();});
render();if(mode==='live')refresh();
// Expose read and navigation only. No agent tool can sign or send a transaction.
if(document.modelContext?.registerTool){const signal=new AbortController();const tools=[{name:'list_launches',title:'Read token launches',description:'Read currently loaded token launches and operating mode. Does not transact.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>({mode,launches:all().map(s=>({id:s.id,name:s.name,symbol:s.symbol,status:status(s,now()),raised:s.raised}))})},{name:'open_launch',title:'Open launch details',description:'Navigate to a loaded launch without buying or signing anything.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async x=>{if(!x||typeof x.id!=='string'||!all().some(s=>s.id===x.id))throw Error('Unknown launch ID');location.hash='/launch/'+encodeURIComponent(x.id);render();return {id:x.id,opened:true,mode};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:signal.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>signal.abort(),{once:true});}
